  9	namespace Application\Composer;
 10	
 11	use Application\Admin\Index\AdminScreenIndexer;
 12	use Application\API\APIManager;
 13	use Application\AppFactory;
 14	use Application\AppFactory\ClassCacheHandler;
 15	use Application\Bootstrap\Screen\TestSuiteBootstrap;
 16	use Application\CacheControl\CacheManager;
 17	use Application\Composer\IconBuilder\IconBuilder;
 18	use Application\Composer\KeywordGlossary\KeywordGlossaryGenerator;
 19	use Application\Composer\ModulesOverview\ModulesOverviewGenerator;
 20	use Application\EventHandler\OfflineEvents\Index\EventIndexer;
 21	use Application\Exception\ApplicationException;
 22	use AppUtils\FileHelper\FileInfo;
 23	use AppUtils\FileHelper\FolderInfo;
 24	use AppUtils\Microtime;
 25	
 26	/**
 27	 * Class with static methods that are used as Composer scripts.
 28	 *
 29	 * See the {@see /composer.json} file for the scripts that are defined.
 30	 *
 31	 * @package Application
 32	 * @subpackage Composer
 33	 */
 34	class ComposerScripts
 35	{
 36	    public const int ERROR_BOOTSTRAP_NOT_FOUND = 169801;
 37	
 38	    public static function build() : void
 39	    {
 40	        self::init();
 41	
 42	        self::clearCaches();
 43	        self::indexOfflineEvents();
 44	        self::indexAdminScreens();
 45	        self::apiMethodIndex();
 46	        self::generateOpenAPISpec();
 47	        self::generateHtaccess();
 48	        self::generateCSSClassesJS();
 49	        self::rebuildIcons();
 50	        self::updateContextGenerateDate();
 51	        self::updateModuleDocumentation();
 52	    }
 53	
 54	    private static function updateModuleDocumentation() : void
 55	    {
 56	        self::doUpdateModuleDocumentation();
 57	    }
 58	
 59	    public static function doUpdateModuleDocumentation() : void
 60	    {
 61	        echo '- Updating module documentation...'.PHP_EOL;
 62	
 63	        $rootFolder = FolderInfo::factory(__DIR__.'/../../../../');
 64	
 65	        (new ModulesOverviewGenerator($rootFolder))->generate();
 66	
 67	        $glossaryOutputPath = rtrim($rootFolder->getPath(), '/').'/docs/agents/project-manifest/module-glossary.md';
 68	
 69	        (new KeywordGlossaryGenerator($rootFolder))->generate($glossaryOutputPath);
 70	
 71	        echo '  DONE.'.PHP_EOL;
 72	    }
 73	
 74	    private static function updateContextGenerateDate() : void
 75	    {
 76	        echo '- Updating context generate date...'.PHP_EOL;
 77	
 78	        FileInfo::factory(__DIR__.'/../../../../.context/generated-at.txt')
 79	            ->putContents(Microtime::createNow()->getISODate(true));
 80	
 81	        echo '  DONE.'.PHP_EOL;
 82	    }
 83	
 84	    public static function clearCaches() : void
 85	    {
 86	        self::init();
 87	
 88	        self::doClearCaches();
 89	    }
 90	
 91	    public static function doClearCaches() : void
 92	    {
 93	        echo '- Clearing all caches...'.PHP_EOL;
 94	
 95	        // Do this manually first, because the cache manager
 96	        // depends on offline events being registered, and
 97	        // which may not exist at this point.
 98	        ClassCacheHandler::clearClassCache();
 99	
100	        CacheManager::getInstance()->clearAll();

101	
102	        echo '  DONE.'.PHP_EOL;
103	    }
104	
105	    /**
106	     * Programmatic seed entry point: truncates all test-database tables,
107	     * invalidates ORM collection caches, then seeds system users, locales,
108	     * and countries — all within a single process.
109	     *
110	     * > **Note for `composer seed-tests`:** The `composer.json` `seed-tests`
111	     * > script does NOT invoke this method. It runs two process-isolated CLI
112	     * > scripts instead (`php tools/seed-truncate.php` then
113	     * > `php tools/seed-insert.php`), which achieves the same result without
114	     * > requiring the `resetCollection()` calls below.
115	     *
116	     * This method is intended for programmatic callers (e.g. application-level
117	     * `ComposerScripts` subclasses) that need truncation + seeding in one
118	     * in-process call. In that scenario the `resetCollection()` calls are
119	     * required: they clear ORM caches that may have been populated during
120	     * bootstrap so that the seed methods' `idExists()` checks query the live
121	     * (post-truncation) database rather than stale in-memory state.
122	     *
123	     * Direct callers must pre-define the <code>APP_SEED_MODE</code> constant
124	     * and call {@see self::init()} before invoking this method.
125	     *
126	     * @throws \Application_Exception
127	     * @throws \Throwable
128	     */
129	    public static function doSeedTests() : void
130	    {
131	        echo '- Seeding test database...'.PHP_EOL;
132	
133	        TestSuiteBootstrap::truncateAllTables();
134	
135	        // Invalidate ORM collection caches that may have been populated during
136	        // bootstrap authentication. Without this, idExists() checks in the
137	        // seed methods would return stale true-values for records that were
138	        // just deleted by the truncation.
139	        AppFactory::createUsers()->resetCollection();
140	        AppFactory::createCountries()->resetCollection();
141	
142	        TestSuiteBootstrap::seedSystemUsers();
143	        TestSuiteBootstrap::seedLocales();
144	        TestSuiteBootstrap::seedCountries();
145	
146	        echo '  DONE.'.PHP_EOL;
147	    }
148	
149	    public static function apiMethodIndex() : void
150	    {
151	        self::init();
152	
153	        self::doApiMethodIndex();
154	    }
155	
156	    public static function indexAdminScreens() : void
157	    {
158	        self::init();
159	
160	        self::doIndexAdminScreens();
161	    }
162	
163	    public static function doIndexAdminScreens() : void
164	    {
165	        echo '- Indexing admin screens...'.PHP_EOL;
166	
167	        $indexer = new AdminScreenIndexer(AppFactory::createDriver());
168	        $indexer->index();
169	
170	        echo sprintf(
171	            '  Found %s screens total (%s content screens).'.PHP_EOL,
172	            $indexer->countScreens(),
173	            $indexer->countContentScreens()
174	        );
175	
176	        echo '  DONE.'.PHP_EOL;
177	    }
178	
179	    public static function indexOfflineEvents() : void
180	    {
181	        self::init();
182	
183	        self::doIndexOfflineEvents();
184	    }
185	
186	    public static function doIndexOfflineEvents() : void
187	    {
188	        echo '- Indexing offline event listeners...'.PHP_EOL;
189	
190	        $indexer = EventIndexer::getInstance();
191	        $indexer->index();
192	
193	        echo sprintf(
194	            '  Found [%s] offline events and [%s] listeners total.'.PHP_EOL,
195	            $indexer->countEvents(),
196	            $indexer->countListeners()
197	        );
198	
199	        echo '  DONE.'.PHP_EOL;
200	    }
201	
202	    public static function doApiMethodIndex() : void
203	    {
204	        self::doClearCaches();
205	
206	        AppFactory::createLogger()->logModeEcho();
207	
208	        APIManager::getInstance()->getMethodIndex()->build();
209	    }
210	
211	    public static function generateOpenAPISpec() : void
212	    {
213	        self::init();
214	
215	        self::doGenerateOpenAPISpec();
216	    }
217	
218	    public static function doGenerateOpenAPISpec() : void
219	    {
220	        echo '- Generating OpenAPI specification...'.PHP_EOL;
221	
222	        try {
223	            $apiDir = self::getFrameworkAPIOutputDirectory();
224	            $outputPath = $apiDir !== '' ? $apiDir.'/openapi.json' : '';
225	            $path = APIManager::getInstance()->generateOpenAPISpec($outputPath);
226	            echo sprintf('  Written to: %s'.PHP_EOL, $path);
227	        } catch (\Throwable $e) {
228	            error_log('OpenAPI spec generation failed: '.$e->getMessage());
229	            echo sprintf('  WARNING: OpenAPI spec generation failed: %s'.PHP_EOL, $e->getMessage());
230	        }
231	
232	        echo '  DONE.'.PHP_EOL;
233	    }
234	
235	    public static function generateHtaccess() : void
236	    {
237	        self::init();
238	
239	        self::doGenerateHtaccess();
240	    }
241	
242	    public static function doGenerateHtaccess() : void
243	    {
244	        echo '- Generating API .htaccess...'.PHP_EOL;
245	
246	        try {
247	            $path = APIManager::getInstance()->generateHtaccess(self::getFrameworkAPIOutputDirectory());
248	            echo sprintf('  Written to: %s'.PHP_EOL, $path);
249	        } catch (\Throwable $e) {
250	            error_log('API .htaccess generation failed: '.$e->getMessage());
251	            echo sprintf('  WARNING: API .htaccess generation failed: %s'.PHP_EOL, $e->getMessage());
252	        }
253	
254	        echo '  DONE.'.PHP_EOL;
255	    }
256	
257	    public static function generateCSSClassesJS() : void
258	    {
259	        self::init();
260	
261	        self::doGenerateCSSClassesJS();
262	    }
263	
264	    public static function doGenerateCSSClassesJS() : void
265	    {
266	        echo '- Generating clientside CSS classes reference...'.PHP_EOL;
267	
268	        new CSSClassesGenerator()->generate();
269	
270	        echo '  DONE.'.PHP_EOL;
271	    }
272	
273	    public static function rebuildIcons() : void
274	    {
275	        self::init();
276	
277	        self::doRebuildIcons();
278	    }
279	
280	    private static function doRebuildIcons() : void
281	    {
282	        echo '- Rebuilding icon methods...'.PHP_EOL;
283	
284	        $root = rtrim(FolderInfo::factory(__DIR__.'/../../../../')->getPath(), '/');
285	
286	        $result = (new IconBuilder(
287	            $root.'/src/themes/default/icons.json',
288	            $root.'/src/classes/UI/Icon.php',
289	            $root.'/src/themes/default/js/ui/icon.js'
290	        ))->build();
291	
292	        if(!$result->isValid())
293	        {
294	            echo sprintf('  ERROR: %s'.PHP_EOL, $result->getErrorMessage());
295	            return;
296	        }
297	
298	        echo '  DONE.'.PHP_EOL;
299	    }

300	
301	    private static bool $initialized = false;
302	
303	    /**
304	     * Returns the absolute path to the framework's test application API directory
305	     * when running within the framework's own GIT package, so that generated files
306	     * (`.htaccess`, `openapi.json`) are written there instead of the default
307	     * `APP_INSTALL_FOLDER/api` which resolves to `/src/api` in the test bootstrap.
308	     *
309	     * Returns an empty string when running inside an application (where the
310	     * `tests/application/api` folder does not exist relative to this file).
311	     *
312	     * @return string Absolute path to `tests/application/api`, or empty string.
313	     */
314	    private static function getFrameworkAPIOutputDirectory() : string
315	    {
316	        $path = __DIR__.'/../../../../tests/application/api';
317	        if(is_dir($path)) {
318	            return (string)realpath($path);
319	        }
320	        return '';
321	    }
322	
323	    /**
324	     * Loads the bootstrap file for the application.
325	     *
326	     * When running within the framework GIT package,
327	     * the test application's bootstrap file is loaded.
328	     * Otherwise, the application's bootstrap file is
329	     * used.
330	     *
331	     * This way, the scripts can be used interchangeably
332	     * when developing the framework and the application.
333	     *
334	     * @return void
335	     */
336	    public static function init() : void
337	    {
338	        if(self::$initialized) {
339	            return;
340	        }
341	
342	        self::$initialized = true;
343	
344	        $bootstrap = __DIR__.'/../../../../tests/bootstrap.php';
345	
346	        $file = FileInfo::factory($bootstrap);
347	        if(!$file->exists()) {
348	            throw new ApplicationException(
349	                'The bootstrap file could not be found at: '.$bootstrap,
350	                '',
351	                self::ERROR_BOOTSTRAP_NOT_FOUND
352	            );
353	        }
354	
355	        require_once (string)$file;
356	
357	        // Removed this, as the application's composer scripts are
358	        // run using the testsuite bootstrap. The bootstrap screen
359	        // is still relevant for applications, however.
360	        //Application_Bootstrap::bootClass(ComposerScriptBootstrap::class);
361	    }
362	}

